import streamlit as st
import pandas as pd
import plotly.express as px
import plotly.graph_objects as go
import os

st.set_page_config(page_title="TB/HIV Predictive System", layout="wide")

st.title("🌍 HIV-Associated Tuberculosis Forecasting & Risk-Stratification System")
st.markdown("Sub-Saharan Africa Deployment Prototype | Projections: 2024–2030")

# Load the deployment dataset generated by your model pipeline
@st.cache_data
def load_data():
    file_path = "TB_HIV_Deployment_Data.xlsx"
    if os.path.exists(file_path):
        return pd.read_excel(file_path, sheet_name='Master_Forecast_Database')
    else:
        st.error(f"Cannot find {file_path}. Please run model_pipeline.py first.")
        return pd.DataFrame()

df = load_data()

if not df.empty:
    # Sidebar Filters
    st.sidebar.header("System Controls")
    selected_country = st.sidebar.selectbox("Select a Country to Profile", options=sorted(df['Country'].unique()))
    map_year = st.sidebar.slider("Select Year for Spatial Risk Map", min_value=2000, max_value=2030, value=2024)
    
    # -------------------------------------------------------------------------
    # 1. CONTINENTAL RISK CHOROPLETH MAP
    # -------------------------------------------------------------------------
    st.subheader(f"Continental Epidemiological Risk Landscape ({map_year})")
    
    map_data = df[df['Year'] == map_year]
    
    # Define standard colors for risk tiers
    risk_colors = {
        'Low Risk': '#00CC96', 
        'Moderate Risk': '#FECB52', 
        'High Risk': '#FFA15A', 
        'Critical / Severe Burden': '#EF553B'
    }
    
    fig_map = px.choropleth(
        map_data, 
        locations="Country", 
        locationmode="country names",
        color="Risk_Tier", 
        color_discrete_map=risk_colors,
        hover_name="Country",
        hover_data={"Incidence": True, "Type": True, "Country": False},
        title=f"HIV-Associated TB Incidence per 100,000 (WHO AFR Region) - {map_year}",
        scope="africa"
    )
    fig_map.update_layout(margin={"r":0,"t":40,"l":0,"b":0})
    st.plotly_chart(fig_map, use_container_width=True)
    
    st.divider()
    
    # -------------------------------------------------------------------------
    # 2. COUNTRY LEVEL LONGITUDINAL FORECAST
    # -------------------------------------------------------------------------
    st.subheader(f"Historical Trajectory & Multi-Step Forecast: {selected_country}")
    
    country_data = df[df['Country'] == selected_country]
    hist_data = country_data[country_data['Type'] == 'Historical']
    fcst_data = country_data[country_data['Type'] == 'Forecast']
    
    # Get current 2030 risk tier
    tier_2030 = fcst_data[fcst_data['Year'] == 2030]['Risk_Tier'].values[0]
    st.info(f"**2030 Projected Epidemiological Risk Tier for {selected_country}:** {tier_2030}")
    
    fig_trend = go.Figure()
    
    # Historical Trace
    fig_trend.add_trace(go.Scatter(
        x=hist_data['Year'], y=hist_data['Incidence'], 
        mode='lines+markers', name='Historical Data (WHO)',
        line=dict(color='royalblue', width=3)
    ))
    
    # Forecast Trace
    fig_trend.add_trace(go.Scatter(
        x=fcst_data['Year'], y=fcst_data['Incidence'], 
        mode='lines+markers', name='Random Forest Forecast',
        line=dict(color='firebrick', width=3, dash='dash')
    ))
    
    # Add Risk Threshold Zones (Background colors)
    fig_trend.add_hrect(y0=100, y1=max(500, country_data['Incidence'].max()+50), fillcolor="red", opacity=0.1, layer="below", line_width=0, annotation_text="Critical Burden (>=100)")
    fig_trend.add_hrect(y0=50, y1=100, fillcolor="orange", opacity=0.1, layer="below", line_width=0, annotation_text="High Risk (50-99)")
    fig_trend.add_hrect(y0=10, y1=50, fillcolor="yellow", opacity=0.1, layer="below", line_width=0, annotation_text="Moderate Risk (10-49)")
    fig_trend.add_hrect(y0=0, y1=10, fillcolor="green", opacity=0.1, layer="below", line_width=0, annotation_text="Low Risk (<10)")
    
    fig_trend.update_layout(
        xaxis_title="Year", 
        yaxis_title="Incidence per 100k",
        hovermode="x unified"
    )
    st.plotly_chart(fig_trend, use_container_width=True)
    
    # Data Table
    with st.expander("View Raw Data Table"):
        st.dataframe(country_data.set_index('Year')[['Incidence', 'Risk_Tier', 'Type']])
